<?php
require_once __DIR__ . '/../common.php';
requireAdmin();
$articles = db()->query("SELECT a.*, c.name AS category_name FROM articles a LEFT JOIN categories c ON c.id=a.category_id ORDER BY a.published_at DESC, a.id DESC")->fetchAll();
$cats = categories();
$edit = null;
if (isset($_GET['edit'])) { $s=db()->prepare('SELECT * FROM articles WHERE id=?'); $s->execute([(int)$_GET['edit']]); $edit=$s->fetch(); }
?><!doctype html><html lang="ur" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>انتظامیہ — <?= e(SITE_NAME) ?></title><link rel="stylesheet" href="admin.css"></head><body><header class="admin-head"><div><strong>📚 <?= e(SITE_NAME) ?></strong><span> — انتظامیہ</span></div><nav><a href="../index.php">ویب سائٹ</a><a href="logout.php">خروج</a></nav></header><main class="wrap"><section class="panel"><h1><?= $edit ? 'مضمون میں ترمیم' : 'نیا مضمون' ?></h1><form method="post" action="save.php"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= e($edit['id'] ?? '') ?>"><label>عنوان</label><input name="title" required value="<?= e($edit['title'] ?? '') ?>"><label>موضوع</label><select name="category_id"><option value="">موضوع منتخب کریں</option><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= isset($edit['category_id'])&&(int)$edit['category_id']===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><label>مختصر تعارف</label><textarea name="excerpt" rows="3"><?= e($edit['excerpt'] ?? '') ?></textarea><label>مضمون کا مکمل متن</label><textarea name="content" rows="18" required><?= e($edit['content'] ?? '') ?></textarea><div class="row"><label class="check"><input type="checkbox" name="featured" value="1" <?= !empty($edit['featured'])?'checked':'' ?>> نمایاں مضمون</label><label class="check"><input type="checkbox" name="published" value="1" <?= !isset($edit['published'])||!empty($edit['published'])?'checked':'' ?>> شائع کریں</label></div><button type="submit">محفوظ کریں</button><?php if($edit): ?><a class="cancel" href="index.php">نئی تحریر</a><?php endif; ?></form></section><section class="panel"><h2>تمام مضامین</h2><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>موضوع</th><th>حالت</th><th>تاریخ</th><th>عمل</th></tr></thead><tbody><?php foreach($articles as $a): ?><tr><td><?= e($a['title']) ?></td><td><?= e($a['category_name'] ?? '—') ?></td><td><?= $a['published']?'شائع شدہ':'مسودہ' ?></td><td><?= e(date('Y-m-d',strtotime($a['published_at']))) ?></td><td><a href="?edit=<?= $a['id'] ?>">ترمیم</a> <form class="inline" method="post" action="delete.php" onsubmit="return confirm('کیا یہ مضمون حذف کرنا ہے؟');"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="danger" type="submit">حذف</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></main></body></html>
